const mode = "direct",
  recipient = "YOUR_ALERT_EMAIL",
  baseUrl = "",
  relayUrl = "YOUR_OPEN_FLOW_WEBHOOK_URL";
if (!["direct", "relay"].includes(mode)) throw Error("Choose direct or relay");
if (mode === "direct" && (!recipient || recipient.startsWith("YOUR_")))
  throw Error("Configure recipient");
if (mode === "relay" && (!relayUrl || relayUrl.startsWith("YOUR_")))
  throw Error("Configure relay URL");
return [{ json: { mode, recipient, baseUrl, relayUrl } }];

function format({ body, baseUrl, handlerId, handlerName }) {
  if (!body || typeof body !== "object" || !body.workflow?.id || !body.workflow?.name)
    throw Error("Missing workflow in error event");
  const source = body.execution?.error ? body.execution : body.trigger?.error ? body.trigger : null;
  if (!source) throw Error("Expected execution or trigger error");
  const redact = (v, k = "") => {
    if (/password|secret|token|authorization|api.?key/i.test(k)) return "[redacted]";
    if (Array.isArray(v)) return v.map((x) => redact(x));
    if (v && typeof v === "object")
      return Object.fromEntries(Object.entries(v).map(([a, b]) => [a, redact(b, a)]));
    return typeof v === "string"
      ? v
          .replace(/(bearer\s+)[^\s,;]+/gi, "$1[redacted]")
          .replace(
            /(["']?(?:api[_-]?key|token|password|secret|authorization)["']?\s*[=:]\s*["']?)[^"'\s,;}]+/gi,
            "$1[redacted]",
          )
      : v;
  };
  const safe = redact(body),
    execution = !!body.execution?.error,
    kind = execution ? "execution error" : "trigger failure",
    name = String(body.workflow.name).replace(/[\r\n]+/g, " "),
    message = String(redact(source.error.message ?? "")).replace(/[\r\n]+/g, " "),
    base = String(baseUrl ?? "").replace(/\/+$/, "");
  if (base && !/^https?:\/\//.test(base)) throw Error("Invalid instance URL");
  const workflowUrl = base
    ? base + "/workflow/" + encodeURIComponent(String(body.workflow.id))
    : "";
  return {
    subject: `Workflow ${body.workflow.id} (${name}) ${kind}: ${message}`,
    text: `Workflow: ${name} (${body.workflow.id})\n${workflowUrl ? "Workflow URL: " + workflowUrl + "\n" : ""}Error handler: ${handlerName || "(not configured)"} (${handlerId || "unknown"})\nType: ${kind}\n\nError event:\n${JSON.stringify(safe, null, 2)}`,
  };
}

const cfg = $("Choose delivery mode").first().json;
return [
  {
    json: format({
      body: $("Error Trigger").first().json,
      baseUrl: cfg.baseUrl,
      handlerId: $workflow.id,
      handlerName: $workflow.name,
    }),
  },
];
